import React, { useCallback, useEffect, useState } from 'react';

import { FocusContext } from '../contexts/FocusContext.js';
import { _useFocusContext } from '../hooks/useFocusContext.js';
import { WithChildren } from '../types/with-children.js';
import { mergeProps as _mergeProps } from '../utils/merge-props.js';

// list of modifier keys commonly used in a mouse or keyboard combination,
// see https://developer.mozilla.org/en-US/docs/Web/API/UI_Events/Keyboard_event_key_values#modifier_keys.
const ignoreMap = [
  'Alt',
  'AltGraph',
  'CapsLock',
  'Control',
  'Fn',
  'FnLock',
  'Hyper',
  'Meta', // Command (Mac), in some browsers also Windows-key
  'NumLock',
  'OS', // Windows-key
  'ScrollLock',
  'Super', // Virtual keyboard key
  'Symbol',
  'SymbolLock',
];

/** Look-up map of all event types and the corresponding modalities. */
const eventTypeMap: Record<string, string> = {
  keydown: 'keyboard',
  keyup: 'keyboard',
  mousedown: 'mouse',
  mousemove: 'mouse',
  MSPointerDown: 'pointer',
  MSPointerMove: 'pointer',
  pointerdown: 'pointer',
  pointermove: 'pointer',
  touchstart: 'touch',
  touchend: 'touch',
  wheel: 'wheel',
};

export type Modality = 'keyboard' | 'pointer' | 'touch' | 'unknown';

/**
 * All navigational keys that should be considered keyboard users,
 * see https://developer.mozilla.org/en-US/docs/Web/API/UI_Events/Keyboard_event_key_values#navigation_keys
 */
const navigationalKeys = [
  'Tab',
  'Esc',
  'Escape',
  ' ',
  'ArrowDown',
  'Down',
  'ArrowUp',
  'Up',
  'ArrowLeft',
  'Left',
  'ArrowRight',
  'Right',
  'End',
  'Home',
  'PageDown',
  'PageUp',
];

/**
 * Provider that can be reused in components for storing the focus context props.
 * Loosely inspired by [what-input-js](https://github.com/ten1seven/what-input/blob/main/src/scripts/what-input.js).
 */
export const FocusProvider = ({ children }: WithChildren) => {
  const [backgroundInertness, setBackgroundInertness] = useState(false);
  const focusContext = _useFocusContext();
  const [modality, setModality] = useState<Modality>('unknown');

  const setKeyboardInputModality = useCallback((event: KeyboardEvent) => {
    if (ignoreMap.includes(event.key)) {
      setModality('pointer');
      return;
    }

    if (!event.target || navigationalKeys.includes(event.key)) {
      setModality('keyboard');
    }
  }, []);

  const setMouseInputModality = useCallback((event: MouseEvent) => {
    switch (eventTypeMap[event.type]) {
      case 'touch':
      case 'pen':
        return setModality('touch');
      case 'mouse':
      case 'pointer':
      case 'wheel':
        return setModality('pointer');
      default:
        return 'unknown';
    }
  }, []);

  useEffect(() => {
    window.addEventListener('pointerdown', setMouseInputModality);
    // we need to rely on the keydown event (already in the capture phase) here so we don't break usages where the event default behavior is prevented or propagation is stopped,
    // which would otherwise get the wrong, initial, modality (unknown); by using the capture phase, we can ensure we set the modality correctly before the other events occur
    window.addEventListener('keydown', setKeyboardInputModality, {
      capture: true,
    });
    window.addEventListener('wheel', setMouseInputModality);

    return () => {
      window.removeEventListener('pointerdown', setMouseInputModality);
      window.removeEventListener('keydown', setKeyboardInputModality, {
        capture: true,
      });
      window.removeEventListener('wheel', setMouseInputModality);
    };
  }, [setKeyboardInputModality, setMouseInputModality]);

  const focusProps = backgroundInertness
    ? {
        inert: 'true',
        tabIndex: -1,
        'aria-hidden': true,
      }
    : { inert: undefined, tabIndex: undefined, 'aria-hidden': false };

  return (
    <FocusContext.Provider
      value={{
        ..._mergeProps(focusContext, {
          backgroundInertness,
          setBackgroundInertness,
          modality,
        }),
      }}
    >
      <div {...focusProps}>{children}</div>
    </FocusContext.Provider>
  );
};
FocusProvider['displayName'] = 'FocusProvider';
